n = 23

# Quadratic residues mod 23
qr = set()
for i in range(1, n):
    qr.add((i*i) % n)
print("Quadratic residues mod 23:", sorted(qr))

def legendre_seq(n):
    qr = set()
    for i in range(1, n):
        qr.add((i*i) % n)
    seq = []
    for i in range(n):
        if i == 0:
            seq.append(1)
        elif i in qr:
            seq.append(1)
        else:
            seq.append(-1)
    return seq

def cyclic_corr(a, b, k, n):
    return sum(a[i] * b[(i+k) % n] for i in range(n))

def check_legendre_pair(x, y, n=23):
    if sum(x) != 1 or sum(y) != 1:
        return False, f"sums: {sum(x)}, {sum(y)}"
    for k in range(1, (n+1)//2 + 1):
        cx = cyclic_corr(x, x, k, n)
        cy = cyclic_corr(y, y, k, n)
        if cx + cy != -2:
            return False, f"k={k}: cx={cx}, cy={cy}, sum={cx+cy}"
    return True, "OK"

x = legendre_seq(23)
print("x:", x)
print("Sum x:", sum(x))

# Try x as both sequences
result, msg = check_legendre_pair(x, x)
print(f"(x,x): {result}, {msg}")
